#include <aircrack-ng/version.h>
#include <stdio.h>

int main(void)
{
    /* Verify version.h was properly generated by configure */
    if (_MAJ != 1 || _MIN != 7 || _SUB_MIN != 0) {
        fprintf(stderr, "FAIL: unexpected version %d.%d.%d\n", _MAJ, _MIN, _SUB_MIN);
        return 1;
    }
    printf("aircrack-ng version: %d.%d.%d\n", _MAJ, _MIN, _SUB_MIN);
    return 0;
}
